// No easing, no acceleration
function linear( t )
{
	return t;
}

// Slight acceleration from zero to full speed
function easeInSine( t )
{
	return -1 * Math.cos( t * ( Math.PI / 2 ) ) + 1;
}

// Slight deceleration at the end
